    # Helper to check duplicates recursively (no loops)
    def has_duplicates(seq, seen=frozenset()):
        if not seq:
            return False
        if seq[0] in seen:
            return True
        return has_duplicates(seq[1:], seen | {seq[0]})

    # Helper to check strictly increasing recursively
    def strictly_increasing(seq):
        if len(seq) <= 1:
            return True
        return seq[0] < seq[1] and strictly_increasing(seq[1:])

    # Helper to check strictly decreasing recursively
    def strictly_decreasing(seq):
        if len(seq) <= 1:
            return True
        return seq[0] > seq[1] and strictly_decreasing(seq[1:])

    # Check duplicates
