    Decodes a string encoded by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return False
    return True

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if n >= 0:
            return sum(int(ch) for ch in s)
        else:
            # For negative numbers: first digit is negative, rest positive
            # s looks like '-12'
            return -int(s[1]) + sum(int(ch) for ch in s[2:])
    return sorted(nums, key=digit_sum)

def solve(s):
    if any(c.isalpha() for c in s):
        return ''.join(c.swapcase() for c in s)
    else:
        return s[::-1]
